-- Modify "sys_modeldev_acceptances" table
ALTER TABLE "public"."sys_modeldev_acceptances" ADD CONSTRAINT "sys_modeldev_acceptances_delivery_counters_ck" CHECK ((attempt_count >= 0) AND (lease_generation >= 0)), ADD CONSTRAINT "sys_modeldev_acceptances_delivery_due_ck" CHECK (((dispatch_state)::text = 'UNKNOWN'::text) OR ((next_attempt_at IS NULL) AND (retry_blocked = false))), ADD CONSTRAINT "sys_modeldev_acceptances_delivery_error_ck" CHECK (last_error_code IS NULL OR last_error_code IN ('INVALID_COMMAND','COMMAND_CONFLICT','OWNER_UNAVAILABLE','INVALID_ACK','LEASE_EXHAUSTED','ATTEMPTS_EXHAUSTED')), ADD CONSTRAINT "sys_modeldev_acceptances_delivery_lease_ck" CHECK ((((dispatch_state)::text = 'DISPATCHING'::text) AND (lease_owner IS NOT NULL) AND ((length((lease_owner)::text) >= 1) AND (length((lease_owner)::text) <= 128)) AND (lease_until IS NOT NULL) AND (lease_generation > 0)) OR (((dispatch_state)::text <> 'DISPATCHING'::text) AND (lease_owner IS NULL) AND (lease_until IS NULL))), ADD CONSTRAINT "sys_modeldev_acceptances_dispatch_state_ck" CHECK (dispatch_state IN ('QUEUED','DISPATCHING','UNKNOWN','ACKED')), ADD CONSTRAINT "sys_modeldev_acceptances_owner_receipt_ck" CHECK ((((dispatch_state)::text = 'ACKED'::text) AND (owner_receipt_canonical IS NOT NULL) AND ((octet_length(owner_receipt_canonical) >= 1) AND (octet_length(owner_receipt_canonical) <= 4096))) OR (((dispatch_state)::text <> 'ACKED'::text) AND (owner_receipt_canonical IS NULL))), ADD COLUMN "attempt_count" bigint NOT NULL DEFAULT 0, ADD COLUMN "lease_generation" bigint NOT NULL DEFAULT 0, ADD COLUMN "lease_owner" character varying NULL, ADD COLUMN "lease_until" timestamptz NULL, ADD COLUMN "next_attempt_at" timestamptz NULL, ADD COLUMN "retry_blocked" boolean NOT NULL DEFAULT false, ADD COLUMN "last_error_code" character varying NULL, ADD COLUMN "owner_receipt_canonical" bytea NULL;
-- Create index "idx_sys_modeldev_acceptances_delivery_due" to table: "sys_modeldev_acceptances"
CREATE INDEX "idx_sys_modeldev_acceptances_delivery_due" ON "public"."sys_modeldev_acceptances" ("retry_blocked", "dispatch_state", "next_attempt_at", "lease_until", "id");
